//! Number-type ranges, derived from Google's libphonenumber metadata.
//!
//! Generated, not written by hand. For every region, each number type gets the
//! shortest national-number prefixes — up to three digits — that no other type
//! of that region produces. Where even three digits leave two types sharing a
//! prefix, as Korea's `158` does between eight-digit representative numbers
//! and ten-digit pagers, the national-number length decides instead. For any
//! one length the rules are therefore prefix-free: at most one matches a
//! number, and a number no rule matches is [`PhoneNumberType::Unknown`] rather
//! than a guess. Classification never affects whether a number is valid.
//!
//! Each rule is packed into a `u32`:
//!
//! | bits      | field                                                         |
//! |-----------|---------------------------------------------------------------|
//! | `16..=26` | prefix key: `d` is `d`, `dd` is `10 + dd`, `ddd` is `110 + ddd` |
//! | `12..=15` | index into [`TYPES`]                                          |
//! | `0..=11`  | lengths the rule covers, bit `length - 4`; `0` for every length |
//!
//! The key keeps the digit count, so `7`, `07` and `007` stay apart, and each
//! region's rules are sorted by it.
//!
//! Calling code 1 is classified from the NANP area-code table in
//! `src/nanp.rs` instead, and is absent here.

use crate::definitions::PhoneNumberType;

/// The type each rule's type index stands for.
pub(crate) const TYPES: [PhoneNumberType; 10] = [
    PhoneNumberType::FixedLine,
    PhoneNumberType::Mobile,
    PhoneNumberType::FixedLineOrMobile,
    PhoneNumberType::TollFree,
    PhoneNumberType::PremiumRate,
    PhoneNumberType::SharedCost,
    PhoneNumberType::PersonalNumber,
    PhoneNumberType::Voip,
    PhoneNumberType::Pager,
    PhoneNumberType::Uan,
];

/// The longest prefix a rule can have.
pub(crate) const MAX_PREFIX_DIGITS: usize = 3;

/// The shortest national-number length a rule's length mask can name.
pub(crate) const MIN_RULE_LENGTH: usize = 4;

